"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3167],{15996:e=>{e.exports=JSON.parse('{"functions":[{"name":"Burst","desc":"Clones `template` at `cf`, scales particle size and speed by `scale`, emits\\nevery emitter once on the next frame (`EmitCount` attribute, default 20) and destroys the\\nclone after `life` seconds. `template` is an `Attachment` (hosted on\\nTerrain) or a `PVInstance`.","params":[{"name":"template","desc":"","lua_type":"Instance"},{"name":"cf","desc":"","lua_type":"CFrame"},{"name":"scale","desc":"","lua_type":"number"},{"name":"life","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":46,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"Warm","desc":"Parks one idle clone of every `CombatVFX` template on `workspace.Terrain`\\n(emitters on, `Rate` 0), so Roblox streams their textures in at join and\\nkeeps them loaded. Without it the first burst of each kind is invisible:\\nits particles die before the texture arrives. Call once per client.","params":[],"returns":[],"function_type":"static","source":{"line":85,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"Tracer","desc":"Full-length tracer beam from `from` to `to` that thins out over\\n`TracerLife`. When every pooled beam is busy the oldest is reused.","params":[{"name":"from","desc":"","lua_type":"Vector3"},{"name":"to","desc":"","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":164,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"MuzzleFlash","desc":"Muzzle flash at `origin`, facing `dir`.","params":[{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"dir","desc":"","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":198,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"isDecalSurface","desc":"True when a decal may go on `inst`: Terrain, or an anchored, mostly opaque\\npart that is not an enemy, a projectile, a moving rock visual, or part of a\\nHumanoid model.","params":[{"name":"inst","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":207,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"Impact","desc":"Impact burst at a bullet hit; a bullet hole when the surface allows it.","params":[{"name":"result","desc":"","lua_type":"RaycastResult"}],"returns":[],"function_type":"static","source":{"line":282,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"explosionScale","desc":"Explosion burst scale for a blast `radius`, clamped to `ExplosionScaleMax`.","params":[{"name":"radius","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":292,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"Explosion","desc":"Explosion burst at `center`, scaled by `radius`; a scorch mark when a world\\nsurface lies within `radius` studs below.","params":[{"name":"center","desc":"","lua_type":"Vector3"},{"name":"radius","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":300,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}},{"name":"EnemyStreak","desc":"Flying enemy bullet streak from `origin` towards `endpoint` at `speed`\\nstuds/s. Stops at the first world hit. Skipped when all `StreakCap` beams\\nare in flight.","params":[{"name":"model","desc":"","lua_type":"Instance"},{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"endpoint","desc":"","lua_type":"Vector3"},{"name":"speed","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":346,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}}],"properties":[],"types":[],"name":"CombatVfx","desc":"Client renderer for every combat burst: muzzle flash, tracer, impact,\\nbullet hole, explosion, scorch mark and the flying enemy bullet streak.\\nTemplates come from `ReplicatedStorage.CombatVFX` (see `CombatVfxConfig`);\\na missing template skips the effect silently. Muzzle flash, impact, tracer\\nand streak hosts are pooled on `workspace.Terrain` (round-robin rings).\\nDecals go on world surfaces only (`isDecalSurface`), live `DecalLife`\\nseconds, fade, and are capped (oldest destroyed first).","realm":["Client"],"source":{"line":14,"path":"src/ReplicatedStorage/SharedModules/CombatVfx.luau"}}')}}]);